423	     * @param owner the persisted owner to represent
424	     * @return the owner DTO with its derived read-only fields populated
425	     */
426	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
427	        owner.setHouseholdSize(householdSize(owner));
428	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
429	        int membershipLevel = membershipLevel(owner);
430	        ownerDto.setMembershipLevel(membershipLevel);
431	        ownerDto.setOwnerSegment(ownerMapper.ownerSegment(owner, membershipLevel));
432	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
433	        ownerDto.setCapacityWarning(capacityWarning(owner.getCity()));
434	        ownerDto.setIdentityKey(identityKey(owner));
435	        Integer possibleDuplicateOf = owner.getPossibleDuplicateOf();
436	        ownerDto.setPossibleDuplicate(possibleDuplicateOf != null);
437	        ownerDto.setPossibleDuplicateOf(possibleDuplicateOf);
