441	    /**
442	     * The {@code membershipLevel} reported for a single owner. Starts from the owner-local derivation
443	     * in {@link OwnerMapper#membershipLevel(Owner)} (the level from the owner's own membership points),
444	     * routed through the controller so the create audit log and the single-owner response agree on one
445	     * value. Unlike the mapper - which sees only the owner - the controller can reach the rest of the
446	     * clinic, so this is the single place a reported membership level is shaped by cross-owner context.
447	     *
448	     * <p>Household ceiling: the reported level is capped at one above the current maximum
449	     * {@linkplain #householdMemberLevel(Owner) level} among the owner's <em>existing</em>
450	     * {@link #householdMembers(Owner) household members} (those sharing its {@code householdId}, other
451	     * than the owner itself). With no existing household member no cap applies and the owner-local level
452	     * is reported unchanged. The cap uses each member's own owner-local level (not their reported,
453	     * capped level), so it depends only on the members' own points and cannot recurse.
454	     *
455	     * @param owner the owner whose reported membership level is wanted
456	     * @return the owner's membership level, capped at one above its household maximum
457	     */
458	    private Integer membershipLevel(Owner owner) {
459	        int ownLevel = ownerMapper.membershipLevel(owner);
460	        java.util.OptionalInt maxHouseholdLevel = householdMembers(owner).stream()
461	            .filter(member -> !java.util.Objects.equals(member.getId(), owner.getId()))
462	            .mapToInt(this::householdMemberLevel)
463	            .max();
464	        if (maxHouseholdLevel.isEmpty()) {
465	            return ownLevel;
466	        }
467	        return Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1);
468	    }
