470	    /**
471	     * The owner-local membership level of a household member, used only as an input to the household
472	     * ceiling in {@link #membershipLevel(Owner)}. The member's {@link Owner#getHouseholdSize()
473	     * household size} is set from its household before the level is derived, so the member's household
474	     * factor is accounted for exactly as it is when the member is reported on its own; the level itself
475	     * comes from the owner-local {@link OwnerMapper#membershipLevel(Owner)}.
476	     *
477	     * @param member an existing member of an owner's household
478	     * @return the member's owner-local membership level
479	     */
480	    private int householdMemberLevel(Owner member) {
481	        member.setHouseholdSize(householdSize(member));
482	        return ownerMapper.membershipLevel(member);
483	    }
