485	    /**
486	     * Canonicalizes the submitted address in place before it is validated, stored and returned, so
487	     * every later step - the required-field check, the persisted value and the response - sees the
488	     * single normalized form produced by {@link AddressNormalizer#normalize(String)} (see that method
489	     * for the trim/collapse/upper-case/abbreviation rules). Normalizing once here, at the head of the
490	     * create flow, keeps address canonicalization in exactly one place rather than spread across the
491	     * steps that read the address.
492	     *
493	     * <p>An address may be supplied either as the structured {@code addressLine1} (with an optional
494	     * {@code addressLine2}) or as the single flat {@code address}, the latter kept for backward
495	     * compatibility. Whichever address fields are supplied are normalized, and the structured fields
496	     * are preferred when present: the flat {@code address} returned is composed as the normalized
497	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
498	     * {@code addressLine2} is present; only when no {@code addressLine1} is supplied does the flat
499	     * {@code address} retain its own normalized value.
500	     *
501	     * @param ownerFieldsDto the submitted owner fields, whose address fields are replaced with their normalized form
502	     */
503	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
504	        String addressLine1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
505	        String addressLine2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
506	        String flatAddress = addressNormalizer.normalize(ownerFieldsDto.getAddress());
507	        ownerFieldsDto.setAddressLine1(addressLine1);
508	        ownerFieldsDto.setAddressLine2(addressLine2);
509	        if (addressLine1 != null && !addressLine1.isBlank()) {
510	            String composed = addressLine2 != null && !addressLine2.isBlank()
511	                ? addressLine1 + " " + addressLine2
512	                : addressLine1;
513	            ownerFieldsDto.setAddress(composed);
514	        } else {
515	            ownerFieldsDto.setAddress(flatAddress);
516	        }
517	    }
