519	    /**
520	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
521	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
522	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
523	     * blank (e.g. {@code "   "}). The offending field names are reported through an
524	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
525	     * as a 400 response carrying an {@code errors} array of field names.
526	     *
527	     * @param ownerFieldsDto the submitted owner fields
528	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
529	     */
530	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
531	        List<String> blankFields = new ArrayList<>();
532	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
533	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
534	        addRequiredAddress(blankFields, ownerFieldsDto);
535	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
536	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
537	        if (!blankFields.isEmpty()) {
538	            throw new InvalidOwnerFieldsException(blankFields);
539	        }
