588	    /**
589	     * Validates the owner's optional {@code postcode} against its {@code city} region. Postcode is
590	     * validated only when present, so an owner created without one is accepted unchanged. A supplied
591	     * postcode is already constrained to four digits by Bean Validation on {@link OwnerFieldsDto}; this
592	     * additionally rejects a well-formed postcode that is out of range for the city's region using the
593	     * shared {@link Region#acceptsPostcode(int) region-to-postcode} table ({@code NSW 2000-2099},
594	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known region accepts any 4-digit
595	     * postcode. An out-of-range postcode is reported through an {@link InvalidOwnerPostcodeException},
596	     * which the {@code ExceptionControllerAdvice} renders as a 400 response.
597	     *
598	     * @param city the city of the owner being created
599	     * @param postcode the supplied postcode, or {@code null} when omitted
600	     * @throws InvalidOwnerPostcodeException if the postcode is out of range for the city's region
601	     */
602	    private void rejectInvalidPostcode(String city, String postcode) {
603	        if (postcode == null || postcode.isBlank()) {
604	            return;
605	        }
606	        Region.forCity(city).ifPresent(region -> {
607	            if (!region.acceptsPostcode(Integer.parseInt(postcode))) {
608	                throw new InvalidOwnerPostcodeException(postcode, city);
609	            }
610	        });
