613	    /**
614	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
615	     * the {@code customerCode}.
616	     */
617	    private static final int CUSTOMER_CODE_HASH_LENGTH = 8;
618	
619	    /**
620	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
621	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the owner's canonical region code resolved from
622	     * its {@code postcode} (falling back to its {@code city}) through the shared
623	     * {@link Region#code(String, String)}, and {@code HASH8} is the first 8 upper-case hex characters
624	     * of the SHA-256 digest of the owner's normalized telephone followed by its last name
625	     * (e.g. {@code 'NSW-1A2B3C4D'}). When this base code collides with an existing owner's
626	     * {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that
627	     * makes the result unique (e.g. {@code 'NSW-1A2B3C4D-2'}), so distinct owners always receive
628	     * distinct customer codes.
629	     *
630	     * @param owner the owner being created, with its telephone already normalized
631	     * @return the formatted, de-duplicated customer code
632	     */
633	    private String customerCode(Owner owner) {
634	        String region = Region.code(owner.getPostcode(), owner.getCity());
635	        String hash8 = sha256Hasher.hexPrefix(owner.getTelephone() + owner.getLastName(), CUSTOMER_CODE_HASH_LENGTH);
636	        String base = region + "-" + hash8;
637	        return deduplicate(base, Owner::getCustomerCode);
638	    }
639	
640	    /**
641	     * Ensures the given {@code base} identifier does not collide with an existing owner's identifier of
642	     * the same kind, read from each owner by {@code identifier}. When no existing owner carries the base
643	     * value it is returned unchanged; otherwise {@code '-<n>'} is appended with the smallest {@code n} of
644	     * 2 or more that yields a value held by no existing owner. Owners for which {@code identifier} yields
645	     * {@code null} are ignored (a {@code null} never collides). Written field-agnostically - like the
646	     * create endpoint's other owner scans ({@link #findExistingOwner(Function, String)},
647	     * {@link #countOwners(Predicate)}) - so the collision search lives in exactly one place and each
648	     * caller supplies only which identifier it de-duplicates.
649	     *
650	     * @param base the computed base identifier to make unique among existing owners
651	     * @param identifier reads the identifier of the same kind from an existing owner (may return {@code null})
652	     * @return the base value, or a {@code '<base>-<n>'} variant that is unique among existing owners
653	     */
654	    private String deduplicate(String base, Function<Owner, String> identifier) {
655	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
656	            .map(identifier)
657	            .filter(java.util.Objects::nonNull)
658	            .collect(java.util.stream.Collectors.toSet());
659	        if (!existing.contains(base)) {
660	            return base;
661	        }
662	        int n = 2;
663	        while (existing.contains(base + "-" + n)) {
664	            n++;
665	        }
666	        return base + "-" + n;
667	    }
668	
669	    /**
670	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
671	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
672	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
673	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
674	     * new owner and surfaced as the read-only {@code namesakeCount} field.
675	     *
676	     * @param firstName the first name of the owner being created
677	     * @param lastName the last name of the owner being created
678	     * @return the number of existing owners with the same first and last name (case-insensitive)
679	     */
680	    private int namesakeCount(String firstName, String lastName) {
681	        return (int) countOwners(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
682	            && equalsIgnoreCase(owner.getLastName(), lastName));
683	    }
684	
685	    private boolean equalsIgnoreCase(String a, String b) {
686	        return a == null ? b == null : a.equalsIgnoreCase(b);
687	    }
688	
689	    /**
690	     * The maximum number of owners a single city may contain. Once a city already holds this many
691	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
692	     */
693	    private static final long MAX_OWNERS_PER_CITY = 50L;
694	
695	    /**
696	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
697	     * owners. Existing owners are matched to the requested city case-insensitively (using
698	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
699	     * the per-city counting used for the customer code. A city at capacity is reported through an
700	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
701	     * 409 Conflict response.
702	     *
703	     * @param city the city of the owner being created
704	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
705	     */
706	    private void rejectCityAtCapacity(String city) {
707	        if (ownersInCity(city) >= MAX_OWNERS_PER_CITY) {
708	            throw new OwnerCityAtCapacityException(city);
709	        }
710	    }
711	
712	    /**
713	     * The soft per-city threshold at or above which the read-only {@code capacityWarning} flag is
714	     * raised. Once a city already holds this many owners (but fewer than the hard
715	     * {@link #MAX_OWNERS_PER_CITY} cap), it is flagged as approaching capacity - a warning well
716	     * below the hard rejection at {@link #MAX_OWNERS_PER_CITY}.
717	     */
718	    private static final long CITY_CAPACITY_WARNING_THRESHOLD = 40L;
719	
720	    /**
721	     * Derives the read-only {@code capacityWarning} flag for an owner: {@code true} when the owner's
722	     * city already holds between {@link #CITY_CAPACITY_WARNING_THRESHOLD} and
723	     * {@link #MAX_OWNERS_PER_CITY} minus one owners (40 to 49, approaching the hard per-city capacity
724	     * limit of {@link #MAX_OWNERS_PER_CITY}), otherwise {@code false}. Uses the same per-city
725	     * accumulation as the hard capacity check ({@link #rejectCityAtCapacity(String)}), so the warning
726	     * band sits directly below the rejection at {@link #MAX_OWNERS_PER_CITY}.
727	     *
728	     * @param city the owner's city
729	     * @return {@code true} if the city is approaching, but has not reached, its owner capacity
730	     */
731	    private boolean capacityWarning(String city) {
732	        long owners = ownersInCity(city);
733	        return owners >= CITY_CAPACITY_WARNING_THRESHOLD && owners < MAX_OWNERS_PER_CITY;
734	    }
735	
736	    /**
737	     * Counts the existing owners whose {@code city} matches the given city, compared
738	     * case-insensitively (see {@link #equalsIgnoreCase(String, String)}). Used by the per-city
739	     * capacity check ({@link #rejectCityAtCapacity(String)}) to count a city's owners.
740	     *
741	     * @param city the city to count owners for
742	     * @return the number of existing owners in that city
743	     */
744	    private long ownersInCity(String city) {
745	        return countOwners(owner -> equalsIgnoreCase(owner.getCity(), city));
746	    }
747	
748	    /**
749	     * The maximum number of owners that may be registered on a single day. Once this many owners
750	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
751	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
752	     */
753	    private static final long MAX_OWNERS_PER_DAY = 100L;
754	
755	    /**
756	     * Resolves the effective registration date for a create request: the value supplied in the
757	     * request when present, otherwise the server's current date. The result is the raw effective
758	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
759	     *
760	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
761	     * @return the supplied date, or today when none was supplied
762	     */
763	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
764	        return suppliedDate != null ? suppliedDate : LocalDate.now();
765	    }
766	
767	    /**
768	     * Rejects a create request whose supplied {@code registrationDate} lies after the server's
769	     * current date. A registration date may be supplied to backdate a create - and is defaulted to
770	     * today when omitted - but it may never be in the future. The check is applied to the raw
771	     * supplied value before the business-day adjustment ({@link #businessDay(LocalDate)}), so a
772	     * future date is rejected regardless of how that adjustment would move it. A future date is
773	     * reported through a {@link FutureRegistrationDateException}, which the
774	     * {@code ExceptionControllerAdvice} renders as a 400 Bad Request response naming the
775	     * {@code registrationDate} field.
776	     *
777	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
778	     * @throws FutureRegistrationDateException if the supplied date is later than the server date
779	     */
780	    private void rejectFutureRegistrationDate(LocalDate suppliedDate) {
781	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
782	            throw new FutureRegistrationDateException(suppliedDate);
783	        }
784	    }
785	
786	    /**
787	     * The fixed list of public holidays that are not business days. A registration date that lands
788	     * on one of these is rolled forward by {@link #businessDay(LocalDate)} to the next non-holiday
789	     * business day, exactly as it is rolled forward off a weekend.
790	     */
791	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
792	        LocalDate.of(2026, 1, 1),
793	        LocalDate.of(2026, 1, 26),
794	        LocalDate.of(2026, 4, 25),
795	        LocalDate.of(2026, 12, 25),
796	        LocalDate.of(2026, 12, 28));
797	
798	    /**
799	     * Adjusts a date so it falls on a business day, rolling forward off weekends and public
800	     * holidays. A Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday} is rolled
801	     * forward one day at a time until the first non-holiday weekday is reached; any other weekday is
802	     * returned unchanged. Applied to the effective registration date so that a weekend or holiday
803	     * value - whether supplied in the request or defaulted to the server date - is stored as the
804	     * next business day, and every value derived from the registration date (such as the membership
805	     * number's year segment and the daily create-limit bucket) uses the adjusted business day.
806	     *
807	     * @param date the effective registration date
808	     * @return the same date when it is a non-holiday weekday, otherwise the next business day
809	     */
810	    private LocalDate businessDay(LocalDate date) {
811	        while (isNonBusinessDay(date)) {
812	            date = date.plusDays(1);
813	        }
814	        return date;
815	    }
816	
817	    /**
818	     * Whether the given date is a weekend day or a listed public holiday, and so not a business day.
819	     *
820	     * @param date the date to test
821	     * @return {@code true} for a Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday}
822	     */
823	    private boolean isNonBusinessDay(LocalDate date) {
824	        DayOfWeek dayOfWeek = date.getDayOfWeek();
825	        return dayOfWeek == DayOfWeek.SATURDAY
826	            || dayOfWeek == DayOfWeek.SUNDAY
827	            || PUBLIC_HOLIDAYS.contains(date);
828	    }
829	
830	    /**
831	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
832	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
833	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
834	     * renders as a 429 Too Many Requests response.
835	     *
836	     * @param date the registration date of the owner being created (today)
837	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
838	     */
839	    private void rejectDailyRegistrationLimit(LocalDate date) {
840	        if (ownersRegisteredOn(date) >= MAX_OWNERS_PER_DAY) {
841	            throw new DailyOwnerRegistrationLimitException(date);
842	        }
843	    }
844	
845	    /**
846	     * Counts the existing owners whose {@code registrationDate} equals the given day. Shared by the
847	     * hard daily create limit ({@link #rejectDailyRegistrationLimit(LocalDate)}) and the soft
848	     * {@code bulkSignupWarning} flag ({@link #bulkSignupWarning(LocalDate)}) so both accumulate a
849	     * day's owners identically.
850	     *
851	     * @param date the registration date to count owners for
852	     * @return the number of existing owners registered on that day
853	     */
854	    private long ownersRegisteredOn(LocalDate date) {
855	        return countOwners(owner -> date.equals(owner.getRegistrationDate()));
856	    }
857	
858	    /**
859	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
860	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
861	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
862	     */
863	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
864	
865	    /**
866	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
867	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
868	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
869	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
870	     * without a registration date, such as seed data) is never flagged.
871	     *
872	     * @param date the owner's registration date (the day it was created), or {@code null}
873	     * @return {@code true} if the day already holds more than the warning threshold of owners
874	     */
875	    private boolean bulkSignupWarning(LocalDate date) {
876	        if (date == null) {
877	            return false;
878	        }
879	        return ownersRegisteredOn(date) > BULK_SIGNUP_WARNING_THRESHOLD;
880	    }
881	
882	    /**
883	     * Rejects a create request whose derived {@code identityKey} exactly equals an existing owner's.
884	     * The identity key is the SHA-256 hex digest over
885	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} (see
886	     * {@link #identityKey(Owner)}) and is the single duplicate check: it subsumes the former separate
887	     * telephone, email and household duplicate blocks. Because the telephone is part of the key, two
888	     * owners with the same last name and postcode but <em>different</em> telephones have different
889	     * identity keys and are both allowed (the second is surfaced instead as a soft
890	     * {@code possibleDuplicate}, see {@link #possibleDuplicateOf(Owner)}); only an exact full-key match
891	     * is a duplicate. Owners flagged deleted are ignored (see {@link #findExistingOwner(Function, String)}),
892	     * and the email-domain blocklist has already been applied earlier in the create flow. A collision is
893	     * reported through a {@link DuplicateOwnerIdentityException}, which the {@code ExceptionControllerAdvice}
894	     * renders as a 409 Conflict response.
895	     *
896	     * @param owner the fully-populated owner being created (telephone normalized, email set)
897	     * @throws DuplicateOwnerIdentityException if an existing (non-deleted) owner has the same identity key
898	     */
899	    private void rejectDuplicateIdentity(Owner owner) {
900	        String key = identityKey(owner);
901	        boolean duplicate = existingOwnerMatches(this::identityKey, key);
902	        if (duplicate) {
903	            throw new DuplicateOwnerIdentityException(key);
904	        }
905	    }
906	
907	    /**
908	     * Computes the soft-match {@code possibleDuplicateOf} for a newly created owner: the id of the
909	     * first existing owner whose {@code identityKey} <em>differs</em> from this owner's yet whose
910	     * {@code lastName} has the same {@linkplain Soundex#encode(String) Soundex code} and whose
911	     * {@code postcode} is equal, or {@code null} when no such owner exists. Because the telephone is
912	     * part of the identity key, an existing owner sharing this owner's last-name sound and postcode but
913	     * carrying a different telephone has a different identity key: it is not a hard duplicate (it passed
914	     * {@link #rejectDuplicateIdentity(Owner)}) and is surfaced here as a soft match instead. An existing
915	     * owner with the <em>same</em> identity key would already have been rejected as a 409 and so is
916	     * excluded by the differing-key condition. A blank {@code postcode} never matches, since two owners
917	     * without a postcode do not share one. The captured id is stored on the new owner and surfaced as
918	     * the read-only {@code possibleDuplicate} / {@code possibleDuplicateOf} fields.
919	     *
920	     * @param owner the fully-populated owner being created (telephone normalized)
921	     * @return the id of the first soft-matching existing owner, or {@code null} when none matches
922	     */
923	    private Integer possibleDuplicateOf(Owner owner) {
924	        if (owner.getPostcode() == null || owner.getPostcode().isBlank()) {
925	            return null;
926	        }
927	        String key = identityKey(owner);
928	        String lastNameSoundex = soundex.encode(owner.getLastName());
929	        return this.clinicService.findAllOwners().stream()
930	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode())
931	                && lastNameSoundex.equals(soundex.encode(existing.getLastName()))
932	                && !key.equals(identityKey(existing)))
933	            .map(Owner::getId)
934	            .filter(java.util.Objects::nonNull)
935	            .findFirst()
936	            .orElse(null);
937	    }
938	
939	    /**
940	     * Reduces an owner to its derived {@code identityKey}: the full lower-case SHA-256 hex digest (see
941	     * {@link Sha256Hasher#hex(String)}) over {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'} -
942	     * the owner's telephone reduced to its canonical E.164 form (see
943	     * {@link TelephoneNormalizer#canonicalize(String)}), the owner's normalized (lower-cased) email or
944	     * the empty string when absent (see {@link EmailNormalizer#normalize(String)}), and the
945	     * {@linkplain Soundex#encode(String) Soundex code} of the owner's last name, joined by {@code '|'}.
946	     * Two owners are duplicates exactly when their whole identity keys are equal. The hashed input never
947	     * contains {@code null} segments, so the create endpoint's single duplicate check compares this one
948	     * value across owners.
949	     *
950	     * @param owner the owner to derive the identity key for
951	     * @return the owner's identity key, a 64-character lower-case hex string
952	     */
953	    private String identityKey(Owner owner) {
954	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
955	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
956	        String email = normalizedEmail == null ? "" : normalizedEmail;
957	        String lastNameSoundex = soundex.encode(owner.getLastName());
958	        return sha256Hasher.hex(telephone + "|" + email + "|" + lastNameSoundex);
959	    }
960	
961	    /**
962	     * Finds the first existing owner that already carries the given comparison {@code key}, derived
963	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null} are
964	     * ignored (a {@code null} key never equals the sought key). The create endpoint's duplicate
965	     * checks reduce both an existing owner and the owner being created to the same canonical key;
966	     * this returns the matched existing owner itself, so a caller can either reject the collision or
967	     * record which owner was matched. Owners flagged deleted (soft-deleted) are excluded, so a
968	     * collision with only a deleted owner is not reported and the create is allowed.
969	     *
970	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
971	     * @param key the canonical key of the owner being created
972	     * @return the first existing owner sharing the key, or empty when none does
973	     */
974	    private Optional<Owner> findExistingOwner(Function<Owner, String> keyExtractor, String key) {
975	        return this.clinicService.findAllOwners().stream()
976	            .filter(owner -> !owner.isDeleted())
977	            .filter(owner -> key.equals(keyExtractor.apply(owner)))
978	            .findFirst();
979	    }
980	
981	    /**
982	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
983	     * from each owner by {@code keyExtractor} (see {@link #findExistingOwner(Function, String)}).
984	     * The create endpoint's duplicate checks use this to reduce both an existing owner and the owner
985	     * being created to the same canonical key and reject a match.
986	     *
987	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
988	     * @param key the canonical key of the owner being created
989	     * @return {@code true} if some existing owner shares the key
990	     */
991	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
992	        return findExistingOwner(keyExtractor, key).isPresent();
993	    }
994	
995	    /**
996	     * Counts the existing owners that satisfy the given {@code predicate}. The create endpoint's
997	     * count-based rules - the per-city capacity, the per-day create limit and the derived
998	     * {@code namesakeCount} - all accumulate owners over {@link ClinicService#findAllOwners()} and
999	     * differ only in the predicate they count by, so the scan-and-count is written in exactly one
1000	     * place and each rule supplies just its own predicate.
1001	     *
1002	     * @param predicate the condition an owner must satisfy to be counted
1003	     * @return the number of existing owners that satisfy the predicate
1004	     */
1005	    private long countOwners(Predicate<Owner> predicate) {
1006	        return this.clinicService.findAllOwners().stream()
1007	            .filter(predicate)
1008	            .count();
1009	    }
1010	
1011	    /**
1012	     * Delimiter joining the canonical {@code lastName} and the {@code postcode} when deriving the
1013	     * shared {@code householdId}.
1014	     */
1015	    private static final String HOUSEHOLD_KEY_DELIMITER = "|";
1016	
1017	    /**
1018	     * Reduces the household {@code lastName} to a canonical form for case-insensitive,
1019	     * whitespace-insensitive comparison: leading and trailing whitespace is trimmed, every run of
1020	     * internal whitespace is collapsed to a single space, and the result is lower-cased using
1021	     * {@link java.util.Locale#ROOT} so comparison is locale-independent.
1022	     *
1023	     * @param value the raw field value, or {@code null}
1024	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
1025	     */
1026	    private String canonicalizeHousehold(String value) {
1027	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
1028	    }
1029	
1030	    /**
1031	     * Derives the deterministic, shared {@code householdId} for an owner from its {@code lastName}
1032	     * and {@code postcode}. The identifier is the first 12 upper-case hex characters of the SHA-256
1033	     * hash of {@code normalizedLastName + '|' + postcode} (see {@link #canonicalizeHousehold(String)}
1034	     * for the last-name normalization), so every owner with the same last name and postcode -
1035	     * regardless of casing or spacing - is automatically assigned the identical value. Owners without
1036	     * a postcode have no household basis and are given no household id ({@code null}).
1037	     *
1038	     * @param owner the owner being created
1039	     * @return the shared household identifier, or {@code null} when the owner has no postcode
1040	     */
1041	    /**
1042	     * Counts the owners in the given owner's household: the existing owners that share its
1043	     * {@code householdId} (see {@link #householdId(Owner)}), which - because the owner being counted is
1044	     * itself persisted before it is decorated - includes the owner. An owner with no {@code householdId}
1045	     * (e.g. no postcode) has no shared household and counts as a household of one. The value feeds the
1046	     * household factor of the owner's membership points.
1047	     *
1048	     * @param owner the owner whose household size is being derived
1049	     * @return the number of owners in the owner's household (at least {@code 1})
1050	     */
1051	    private int householdSize(Owner owner) {
1052	        if (owner.getHouseholdId() == null) {
1053	            return 1;
1054	        }
1055	        return householdMembers(owner).size();
1056	    }
1057	
1058	    /**
1059	     * The existing owners that make up the given owner's household: those sharing its
1060	     * {@code householdId} (see {@link #householdId(Owner)}). An owner with no {@code householdId}
1061	     * (e.g. no postcode) belongs to no shared household, so the result is empty. Whether the owner
1062	     * itself appears depends on when the scan runs relative to the create's save: a scan taken after
1063	     * the owner is persisted (as the {@link #householdSize(Owner) household size} derivation is)
1064	     * counts it among its household, while one taken before the save sees only the owners already
1065	     * present. Holding the household lookup in one place lets every household-derived value read the
1066	     * same set of members.
1067	     *
1068	     * @param owner the owner whose household members are wanted
1069	     * @return the owners sharing the owner's household, or an empty list when it has no household
1070	     */
1071	    private List<Owner> householdMembers(Owner owner) {
1072	        String household = owner.getHouseholdId();
1073	        if (household == null) {
1074	            return List.of();
1075	        }
1076	        return this.clinicService.findAllOwners().stream()
1077	            .filter(existing -> household.equals(existing.getHouseholdId()))
1078	            .toList();
1079	    }
1080	
1081	    private String householdId(Owner owner) {
1082	        String postcode = owner.getPostcode();
1083	        if (postcode == null || postcode.isBlank()) {
1084	            return null;
1085	        }
1086	        String key = canonicalizeHousehold(owner.getLastName()) + HOUSEHOLD_KEY_DELIMITER + postcode;
1087	        return sha256Hasher.hexPrefix(key, HOUSEHOLD_ID_LENGTH);
1088	    }
1089	
1090	    /**
1091	     * Number of leading hex characters of the household hash retained as the shared
1092	     * {@code householdId}.
1093	     */
1094	    private static final int HOUSEHOLD_ID_LENGTH = 12;
1095	}
