22	
23	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
24	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
25	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
