27	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
28	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
29	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
30	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
31	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
32	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
33	    @Mapping(target = "locality", expression = "java(locality(owner))")
34	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
35	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
36	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
37	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
38	    @Mapping(target = "bulkSignupWarning", ignore = true)
39	    @Mapping(target = "capacityWarning", ignore = true)
40	    @Mapping(target = "identityKey", ignore = true)
41	    @Mapping(target = "possibleDuplicate", ignore = true)
42	    @Mapping(target = "possibleDuplicateOf", ignore = true)
43	    OwnerDto toOwnerDto(Owner owner);
44	
45	    /**
46	     * Derives the owner's {@code selfLink}: the canonical link to the owner, formatted
47	     * {@code '/api/owners/' + id}. Returns {@code null} when the owner has no id (e.g. an
48	     * unpersisted owner), in which case the field is absent from the response.
49	     *
50	     * @param owner the owner being mapped
51	     * @return the owner's self link, or {@code null} when the owner has no id
52	     */
53	    default String selfLink(Owner owner) {
54	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
55	    }
56	
57	    /**
58	     * Derives the owner's {@code salutation} from its optional {@code title} and its {@code lastName}:
59	     * the title, a single space and the last name when a title is present (e.g. {@code 'DR Franklin'}),
60	     * otherwise just the last name. A {@code null} or blank title yields the bare last name.
61	     *
62	     * @param owner the owner being mapped
63	     * @return the derived salutation
64	     */
65	    default String salutation(Owner owner) {
66	        String title = owner.getTitle();
67	        if (title == null || title.isBlank()) {
68	            return owner.getLastName();
69	        }
70	        return title + " " + owner.getLastName();
71	    }
72	
73	    /**
74	     * Derives the owner's {@code contactPreference} from the owner's own fields:
75	     * {@code EMAIL} when an email is present, otherwise {@code PHONE}.
76	     *
77	     * @param owner the owner being mapped
78	     * @return the derived contact preference
79	     */
80	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
81	        return hasEmail(owner) ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
82	    }
83	
84	    /**
85	     * Reports whether the owner has a usable {@code email}: present and not blank (whitespace-only).
86	     * The presence of an email drives several derived fields (such as the {@code contactPreference}
87	     * and the {@code membershipLevel}), so the "has an email" test is written in exactly one place
88	     * rather than repeated at each use.
89	     *
90	     * @param owner the owner being mapped
91	     * @return {@code true} when the owner has a non-blank email
92	     */
93	    default boolean hasEmail(Owner owner) {
94	        return owner.getEmail() != null && !owner.getEmail().isBlank();
95	    }
96	
97	    /**
98	     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against the owner's
99	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} for 18 to 64, and
100	     * {@code SENIOR} for 65 and over. Returns {@code null} when no birth date is present, in which
101	     * case the field is absent from the response. The age in whole years is the number of complete
102	     * years between the birth date and the registration date (see {@link java.time.Period}); when the
103	     * registration date is somehow absent the current date is used as the reference.
104	     *
105	     * @param owner the owner being mapped
106	     * @return the derived age band, or {@code null} when no birth date is present
107	     */
108	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
109	        java.time.LocalDate birthDate = owner.getBirthDate();
110	        if (birthDate == null) {
111	            return null;
112	        }
113	        java.time.LocalDate reference = owner.getRegistrationDate() != null
114	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
115	        int age = java.time.Period.between(birthDate, reference).getYears();
116	        if (age < 18) {
117	            return OwnerDto.AgeBandEnum.MINOR;
118	        }
119	        if (age < 65) {
120	            return OwnerDto.AgeBandEnum.ADULT;
121	        }
122	        return OwnerDto.AgeBandEnum.SENIOR;
123	    }
124	
125	    /**
126	     * Derives the owner's {@code locality} as the {@code REGION} segment of its {@code customerCode}
127	     * (the part before the {@code '-'}), which is the owner's canonical region code baked into the
128	     * region-and-hash identity {@code '<REGION>-<HASH8>'}. When no customer code is present (e.g. seed
129	     * data) it falls back to resolving the region directly from the owner's {@code postcode} and
130	     * {@code city} through the shared {@link Region#code(String, String)}. Reading the region from the
131	     * identity keeps the locality consistent with the code an owner is issued.
132	     *
133	     * @param owner the owner being mapped
134	     * @return the derived locality
135	     */
136	    default String locality(Owner owner) {
137	        String code = owner.getCustomerCode();
138	        if (code == null) {
139	            return Region.code(owner.getPostcode(), owner.getCity());
140	        }
141	        return regionPrefix(code);
142	    }
143	
144	    /**
145	     * The {@code REGION} segment of a region-and-hash identity {@code code}: the part before the first
146	     * {@code '-'} (e.g. {@code 'NSW'} for {@code 'NSW-1A2B3C4D'}), or the whole {@code code} when it
147	     * carries no {@code '-'}. Holding the "read the region back out of the identity code" rule in one
148	     * place keeps the derived {@link #locality(Owner) locality} consistent with the code an owner is
149	     * issued, and gives the region parse a single home as the identity code's format evolves.
150	     *
151	     * <p>Declared {@code private} so MapStruct treats it as an internal helper of {@link #locality(Owner)}
152	     * rather than as an implicit {@code String}-to-{@code String} mapping method it might auto-apply to
153	     * unrelated string properties.
154	     *
155	     * @param code the region-and-hash identity code the region is read from
156	     * @return the leading {@code REGION} segment of the code
157	     */
158	    private String regionPrefix(String code) {
159	        int dash = code.indexOf('-');
160	        return dash >= 0 ? code.substring(0, dash) : code;
161	    }
162	
163	    /**
164	     * Derives the owner's {@code timezone} as the IANA name for its {@link #locality(Owner) locality}
165	     * region, resolved through the shared fixed region-to-timezone table
166	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
167	     * {@code QLD -> Australia/Brisbane}) in {@link Region#timezoneForCode(String)}. Deriving it from
168	     * the same locality keeps the timezone consistent with the region the owner is labelled with.
169	     * Returns {@code null} when the locality has no known timezone (such as an {@code UNKNOWN}
170	     * region), in which case the field is absent from the response.
171	     *
172	     * @param owner the owner being mapped
173	     * @return the derived IANA timezone name, or {@code null} when the region has no known timezone
174	     */
175	    default String timezone(Owner owner) {
176	        return Region.timezoneForCode(locality(owner));
177	    }
178	
179	    /**
180	     * Derives the owner's {@code ownerSegment}, formatted {@code '<TIER>_<AREA>'}. {@code TIER} is
181	     * {@code PREMIUM} when the owner's {@link #membershipLevel(Owner) membershipLevel} is {@code 3} or
182	     * more, otherwise {@code STANDARD}. {@code AREA} is {@code METRO} when the owner's
183	     * {@link #locality(Owner) locality} is a known region (NSW, VIC or QLD), otherwise
184	     * {@code REGIONAL}. Deriving both parts from the same locality and membership level keeps the
185	     * segment consistent with those fields.
186	     *
187	     * @param owner the owner being mapped
188	     * @return the derived owner segment
189	     */
190	    default OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
191	        return ownerSegment(owner, membershipLevel(owner));
192	    }
193	
194	    /**
195	     * Derives the owner's {@code ownerSegment} for a given reported {@code membershipLevel}, so a
196	     * caller that has shaped the level with cross-owner context (such as the controller's household
197	     * cap) can keep the segment's {@code TIER} consistent with the level it reports. {@code TIER} is
198	     * {@code PREMIUM} when {@code membershipLevel} is {@code 3} or more, otherwise {@code STANDARD};
199	     * {@code AREA} is {@code METRO} when the owner's {@link #locality(Owner) locality} is a known
200	     * region (NSW, VIC or QLD), otherwise {@code REGIONAL}.
201	     *
202	     * @param owner the owner being mapped
203	     * @param membershipLevel the membership level to base the tier on
204	     * @return the derived owner segment
205	     */
206	    default OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner, int membershipLevel) {
207	        String tier = membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
208	        String area = Region.forCode(locality(owner)).isPresent() ? "METRO" : "REGIONAL";
209	        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
210	    }
211	
212	    /**
213	     * Derives the owner's {@code membershipPoints} from the owner's factors. Starts at {@code 0},
214	     * adds {@code 2} when an email is present, adds {@code 1} when the owner's {@code namesakeCount}
215	     * is {@code 0}, adds {@code 2} for a household of {@code 3} or more (see
216	     * {@link Owner#getHouseholdSize()}), and adds {@code 3} when the owner's tenure &mdash; the number
217	     * of elapsed fiscal years between its {@code registrationDate} and the current date &mdash; exceeds
218	     * one fiscal year (see {@link #tenureFiscalYears(Owner)}).
219	     *
220	     * @param owner the owner being mapped
221	     * @return the derived membership points
222	     */
223	    default Integer membershipPoints(Owner owner) {
224	        int points = 0;
225	        if (hasEmail(owner)) {
226	            points += 2;
227	        }
228	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
229	        if (uniqueName) {
230	            points += 1;
231	        }
232	        if (owner.getHouseholdSize() >= 3) {
233	            points += 2;
234	        }
235	        if (tenureFiscalYears(owner) > 1) {
236	            points += 3;
237	        }
238	        return points;
239	    }
240	
241	    /**
242	     * Maps the owner's {@code membershipPoints} to its numeric {@code membershipLevel}: level
243	     * {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
244	     * {@code 4} for {@code 6} or more points.
245	     *
246	     * @param owner the owner being mapped
247	     * @return the derived membership level, between {@code 1} and {@code 4}
248	     */
249	    default Integer membershipLevel(Owner owner) {
250	        int points = membershipPoints(owner);
251	        if (points <= 1) {
252	            return 1;
253	        }
254	        if (points <= 3) {
255	            return 2;
256	        }
257	        if (points <= 5) {
258	            return 3;
259	        }
260	        return 4;
261	    }
262	
263	    /**
264	     * Computes the owner's tenure as the number of elapsed fiscal years between the owner's
265	     * {@code registrationDate} and the current date: the fiscal year of "now" minus the fiscal year
266	     * of the registration date (see {@link #fiscalYearNumber(java.time.LocalDate)}). An owner
267	     * registered and read within the same fiscal year has a tenure of {@code 0}; each subsequent
268	     * fiscal year that has started adds one. Returns {@code 0} when no registration date is present,
269	     * so an owner without a registration date has no tenure.
270	     *
271	     * @param owner the owner being mapped
272	     * @return the owner's tenure in elapsed fiscal years, or {@code 0} when no registration date is present
273	     */
274	    default long tenureFiscalYears(Owner owner) {
275	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
276	        if (registrationDate == null) {
277	            return 0;
278	        }
279	        return (long) fiscalYearNumber(java.time.LocalDate.now()) - fiscalYearNumber(registrationDate);
280	    }
281	
282	    /**
283	     * Computes the calendar year that identifies the fiscal year containing {@code date}. The fiscal
284	     * year starts on 1 July and is labelled by the calendar year in which it starts, so a date on or
285	     * after 1 July belongs to that same year's fiscal year, while a date before 1 July belongs to the
286	     * previous year's fiscal year (e.g. {@code 2026-09-06} yields {@code 2026} and {@code 2026-06-15}
287	     * yields {@code 2025}).
288	     *
289	     * @param date the date whose fiscal year is wanted
290	     * @return the calendar year the fiscal year starts in
291	     */
292	    default int fiscalYearNumber(java.time.LocalDate date) {
293	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() : date.getYear() - 1;
294	    }
295	
296	    /**
297	     * Derives the owner's {@code fiscalYear}, formatted {@code 'FY<YY>'}, where {@code YY} is the last
298	     * two digits of the fiscal year of the (business-day-adjusted) {@code registrationDate} (e.g.
299	     * {@code 'FY26'}). Returns {@code null} when no registration date is present.
300	     *
301	     * @param owner the owner being mapped
302	     * @return the formatted fiscal year, or {@code null} when no registration date is present
303	     */
304	    default String fiscalYear(Owner owner) {
305	        String segment = fiscalYearSegment(owner);
306	        return segment == null ? null : "FY" + segment;
307	    }
308	
309	    /**
310	     * The two-digit {@code YY} fiscal-year segment of the owner's business-day-adjusted
311	     * {@code registrationDate}: the last two digits of its
312	     * {@linkplain #fiscalYearNumber(java.time.LocalDate) fiscal year}, zero-padded (e.g. {@code '26'}).
313	     * This is the single {@code YY} shared by the {@code fiscalYear} field ({@code 'FY<YY>'}) and the
314	     * {@code membershipNumber} ({@code '<customerCode>-M<YY>'}), so the two derive the fiscal year
315	     * identically. Returns {@code null} when no registration date is present.
316	     *
317	     * @param owner the owner being mapped
318	     * @return the two-digit fiscal-year segment, or {@code null} when no registration date is present
319	     */
320	    default String fiscalYearSegment(Owner owner) {
321	        if (owner.getRegistrationDate() == null) {
322	            return null;
323	        }
324	        return String.format("%02d", fiscalYearNumber(owner.getRegistrationDate()) % 100);
325	    }
326	
327	    /**
328	     * Builds the owner's {@code membershipNumber}, formatted {@code '<customerCode>-M<YY>'},
329	     * where {@code YY} is the last two digits of the fiscal year of the (business-day-adjusted)
330	     * {@code registrationDate} (e.g. {@code 'NSW-1A2B3C4D-M26'}). Returns {@code null} when either the
331	     * customer code or the registration date is absent.
332	     *
333	     * @param owner the owner being mapped
334	     * @return the formatted membership number, or {@code null} when it cannot be derived
335	     */
336	    default String membershipNumber(Owner owner) {
337	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
338	            return null;
339	        }
340	        return owner.getCustomerCode() + "-M" + fiscalYearSegment(owner);
341	    }
342	
343	    /**
344	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
345	     * contained in the {@code customerCode} (non-digit characters, such as the {@code '<REGION>-'}
346	     * prefix, the separator and the hex letters {@code A-F}, are ignored). Returns {@code null} when
347	     * the customer code is absent.
348	     *
349	     * @param owner the owner being mapped
350	     * @return the Luhn check digit, or {@code null} when no customer code is present
351	     */
352	    default Integer checkDigit(Owner owner) {
353	        String code = owner.getCustomerCode();
354	        if (code == null) {
355	            return null;
356	        }
357	        return Luhn.checkDigit(code);
358	    }
359	
360	    /**
361	     * Formats the owner's stored E.164 {@code telephone} for human display: the country calling
362	     * code, a space, then the national-significant digits grouped in threes separated by spaces
363	     * (e.g. {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw {@code telephone}
364	     * field keeps the unformatted E.164 value. The split between the country code and the national
365	     * digits mirrors the recognised calling codes of the {@code TelephoneNormalizer}: Australian
366	     * {@code +61} (9 national digits) and North American {@code +1} (10); an unrecognised or
367	     * malformed value falls back to a single leading digit. Returns the value unchanged when it is
368	     * {@code null}, blank, or not in E.164 form.
369	     *
370	     * @param owner the owner being mapped
371	     * @return the human-formatted telephone, or the raw value when it cannot be formatted
372	     */
373	    default String telephoneDisplay(Owner owner) {
374	        String telephone = owner.getTelephone();
375	        if (telephone == null || telephone.isBlank() || !telephone.startsWith("+")) {
376	            return telephone;
377	        }
378	        String digits = telephone.substring(1);
379	        int codeLength = (digits.startsWith("61") && digits.length() == 2 + 9) ? 2 : 1;
380	        String countryCode = digits.substring(0, codeLength);
381	        String national = digits.substring(codeLength);
382	        StringBuilder grouped = new StringBuilder();
383	        for (int i = 0; i < national.length(); i++) {
384	            if (i > 0 && i % 3 == 0) {
385	                grouped.append(' ');
386	            }
387	            grouped.append(national.charAt(i));
388	        }
389	        return "+" + countryCode + " " + grouped;
390	    }
391	
392	    Owner toOwner(OwnerDto ownerDto);
393	
394	    @Mapping(target = "id", ignore = true)
395	    @Mapping(target = "pets", ignore = true)
396	    Owner toOwner(OwnerFieldsDto ownerDto);
397	
398	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
399	
400	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
401	
402	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
403	        OwnerPageDto ownerPageDto = new OwnerPageDto();
404	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
405	        ownerPageDto.setPage(ownerPage.getNumber());
406	        ownerPageDto.setSize(ownerPage.getSize());
407	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
408	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
409	        return ownerPageDto;
410	    }
411	}
