 * @return the leading {@code REGION} segment of the member id
 */
private String regionPrefix(String memberId) {
    for (Region region : Region.values()) {
        if (memberId.startsWith(region.name())) {
            return region.name();
        }
    }
    return Region.UNKNOWN_CODE;
}

